from pathlib import Path
from collections import Counter
import cv2,numpy as np
from run_court_initialization_trial import ROOT,BASE,OUT,load,read,sha,dump,write
from court_initialization_guard import PARAMETERS
def main():
    assert not (OUT/'final_verification.json').exists();p=load(OUT/'protocol.json');run=load(OUT/'run_result.json');assert run['baseline_exact_cases']==15;assert all(sha(Path(n))==h for n,h in p['protected_input_hashes'].items())
    cols=['source_frame','player_slot','track_id','x1','y1','x2','y2','identity_source','assignment_cost','alternative_cost_margin'];key=lambda r:tuple(str(r[k]) for k in cols)
