        assert all(sha(Path(n))==h for n,h in q['protected_input_hashes'].items());assert all(sha(full/n)==h for n,h in result['artifact_hashes'].items());assert v['prefix_feature_values_equal_AI_assisted'] and v['prefix_slot_raw_boxes_equal_AI_assisted']
        times=q['requested_input_frames'];assert times==load(BASE/f'cohort_tracking/case_{tag}/protocol.json')['requested_input_frames']
